    if not eq or key not in keys:
        errors.append(f"{number}: unknown or ignored line {line!r}")
        continue
    if key == "gsaspectratio":
        aspect = value
    if key != "patch":
        continue
    if group is None:
        errors.append(f"{number}: patch outside a [group] (legacy, disables patches.zip)")
