import re, sys
path = "dolphin-ini/GHBE99.ini"
sections, current = {}, None
for raw in open(path, encoding="utf-8"):
    line = raw.strip()
    if not line:
        continue
    if line.startswith("[") and line.endswith("]"):
        current = sections.setdefault(line[1:-1], [])
        continue
    if current is not None:
        current.append(line)

def number(text, base=0):
    # strtoull rules: base 0 auto-detects 0x hex, leading-0 octal, else decimal.
    text = text.strip()
    if base == 0:
        if re.fullmatch(r"0[xX][0-9A-Fa-f]+", text):
            return int(text, 16)
        if re.fullmatch(r"0[0-7]*", text):
            return int(text, 8)
        return int(text, 10) if re.fullmatch(r"[1-9][0-9]*", text) else None
    return int(text, 16) if re.fullmatch(r"[0-9A-Fa-f]+", text) else None

errors, onframe, name = [], {}, None
for line in sections.get("OnFrame", []):
    if line.startswith("$"):
        name = line[1:].strip()
        onframe[name] = []
        continue
    items = line.replace("=", ":", 1).split(":")
    address = number(items[0]) if len(items) >= 3 else None
    value = number(items[2]) if len(items) >= 3 else None
    if address is None or value is None or items[1] not in ("byte", "word", "dword"):
        errors.append(f"OnFrame line dropped by Dolphin: {line!r}")
        continue
    onframe.setdefault(name, []).append((address, items[1], value))
if onframe.get("Skip intro") != [(0x80123456, "dword", 0x60000000)]:
    errors.append(f"Skip intro should be one dword write of 0x60000000 to 0x80123456, got {onframe.get('Skip intro')}")
if onframe.get("Max coins") != [(0x803A1F20, "word", 0x3E7)]:
    errors.append(f"Max coins should be one word write of 0x3E7 to 0x803A1F20, got {onframe.get('Max coins')}")
gecko, name = {}, None
for line in sections.get("Gecko", []):
    if line.startswith("$"):
        name = line[1:].split("[")[0].strip()
        gecko[name] = []
    elif not line.startswith("*") and name:
        words = line.split()
        if len(words) >= 2:
            gecko[name].append((number(words[0], 16), number(words[1], 16)))
if gecko.get("Infinite health") != [(0x04345678, 0x3E7)]:
    errors.append(f"Infinite health should keep 04345678 000003E7, got {gecko.get('Infinite health')}")
for section, names in (("OnFrame_Enabled", ["Skip intro", "Max coins"]), ("Gecko_Enabled", ["Infinite health"])):
    listed = {line[1:].strip() for line in sections.get(section, []) if line.startswith("$")}
    for wanted in names:
        if wanted not in listed:
            errors.append(f"[{section}] should list ${wanted}")
print("\n".join(errors) or "OK")
sys.exit(1 if errors else 0)
